#include <iostream>
#include <string>
using namespace std;

class Speaker {
public:
    virtual void speak() const = 0;
    virtual ~Speaker() {}
};

class Cat : public Speaker {
    string name;
public:
    Cat(string n) : name(n) {}
    void speak() const override {
        cout << name << "：喵～" << endl;
    }
};

class Fish : public Speaker {
    string name;
public:
    Fish(string n) : name(n) {}
    void speak() const override {
        cout << name << "：咕噜咕噜～" << endl;
    }
};

int main() {
    Cat c("小橘");
    Fish f("大肥鱼");
    Speaker* roster[2] = { &c, &f };
    for (int i = 0; i < 2; i++) {
        roster[i]->speak();
    }
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Animal {
protected:
    string name;
public:
    Animal(string n) : name(n) {}
    virtual void speak() const = 0;
    void showName() const {
        cout << "本喵叫 " << name << endl;
    }
};

class Cat : public Animal {
public:
    Cat(string n) : Animal(n) {}
    void speak() const override {
        cout << name << "：喵～" << endl;
    }
};

int main() {
    Cat c("煤球");
    Animal& r = c;
    r.showName();
    r.speak();
    return 0;
}
